package dashboard

import (
	"time"

	"github.com/wuxu92/azwise"
)

// DashboardGrafana provides resource knowledge for Microsoft.Dashboard/grafana.
//
// Contributing Terraform resource:
//   - azurerm_dashboard_grafana
//
// Sources:
//   - terraform-provider-azurerm internal/services/dashboard/dashboard_grafana_resource.go
//     (schema Arguments L87-259, Attributes L261-281, Create timeout L285, Read L457,
//     Update L375, Delete L576, expandCreateForDashboardGrafana L326-371,
//     expandSMTPConfigurationModel L629-651, expandGrafanaIntegrationsModel L653-661)
//   - go-azure-sdk resource-manager/dashboard/2025-08-01/managedgrafanas:
//     model_managedgrafana.go, model_managedgrafanaproperties.go, model_resourcesku.go,
//     model_smtp.go, model_grafanaconfigurations.go, model_grafanaintegrations.go,
//     constants.go (enum values).
//
// Notes:
//   - sku maps to the top-level ARM sku.name (ResourceSku.Name, a plain string), and
//     sku_size to sku.size (Size enum). Both are ForceNew.
//   - The Enabled/Disabled toggles in AzureRM map to string enums in ARM:
//     api_key_enabled -> properties.apiKey (Enabled/Disabled),
//     deterministic_outbound_ip_enabled -> properties.deterministicOutboundIP,
//     public_network_access_enabled -> properties.publicNetworkAccess,
//     zone_redundancy_enabled -> properties.zoneRedundancy.
//   - identity uses SystemOrUserAssignedIdentityOptionalForceNew (ForceNew envelope-level).
//   - grafana_major_version has no SDK enum (GrafanaMajorVersion is *string); AzureRM
//     restricts it to "12"/"13", mirrored here as a StringRule.
type DashboardGrafana struct {
	azwise.BaseKnowledge
}

var _ azwise.ResourceKnowledge = (*DashboardGrafana)(nil)

// NewDashboardGrafana returns knowledge for the Microsoft.Dashboard/grafana resource.
func NewDashboardGrafana() *DashboardGrafana {
	return &DashboardGrafana{
		BaseKnowledge: azwise.BaseKnowledge{
			ResourceType: "Microsoft.Dashboard/grafana",
			ApiVersions:  []string{"2025-08-01"},
			SoftDelete:   false,
			TimeoutsConfig: &azwise.Timeouts{
				Create: 30 * time.Minute,
				Read:   5 * time.Minute,
				Update: 30 * time.Minute,
				Delete: 30 * time.Minute,
			},
			ForceNew: []azwise.ForceNewRule{
				{PropertyPath: "name"},
				{PropertyPath: "identity"},
				{PropertyPath: "sku.name"},
				{PropertyPath: "sku.size"},
				{PropertyPath: "properties.zoneRedundancy"},
			},
			StringRules: []azwise.StringRule{
				// name (resource name; empty PropertyPath). 2-23 chars.
				{
					PropertyPath: "",
					Regex:        `^[a-zA-Z][-a-zA-Z\d]{0,21}[a-zA-Z\d]$`,
					MinLength:    2,
					MaxLength:    23,
					Message:      "name must be 2-23 characters, contain only letters, numbers and dashes, begin with a letter and end with a letter or digit",
				},
				{
					PropertyPath:  "properties.autoGeneratedDomainNameLabelScope",
					AllowedValues: []string{"TenantReuse"},
					Message:       "must be TenantReuse",
				},
				{
					PropertyPath:  "properties.grafanaMajorVersion",
					AllowedValues: []string{"12", "13"},
					Message:       "must be one of 12 or 13",
				},
				{
					PropertyPath:  "sku.name",
					AllowedValues: []string{"Standard", "Essential"},
					Message:       "must be Standard (Essential is deprecated and removed in provider v5.0)",
				},
				{
					PropertyPath:  "sku.size",
					AllowedValues: []string{"X1", "X2"},
					Message:       "must be one of X1 or X2",
				},
				{
					PropertyPath:  "properties.grafanaConfigurations.smtp.startTLSPolicy",
					AllowedValues: []string{"MandatoryStartTLS", "NoStartTLS", "OpportunisticStartTLS"},
					Message:       "must be one of MandatoryStartTLS, NoStartTLS, or OpportunisticStartTLS",
				},
			},
			SensitiveFields: []string{
				"properties.grafanaConfigurations.smtp.password",
			},
			// Server-populated, read-only ARM properties (Computed attributes in AzureRM).
			ComputedFields: []string{
				"properties.endpoint",
				"properties.grafanaVersion",
				"properties.outboundIPs",
			},
			DefaultValues: []azwise.DefaultValue{
				{PropertyPath: "properties.apiKey", Value: "Disabled"},
				{PropertyPath: "properties.autoGeneratedDomainNameLabelScope", Value: "TenantReuse"},
				{PropertyPath: "properties.deterministicOutboundIP", Value: "Disabled"},
				{PropertyPath: "properties.publicNetworkAccess", Value: "Enabled"},
				{PropertyPath: "properties.zoneRedundancy", Value: "Disabled"},
				{PropertyPath: "sku.name", Value: "Standard"},
				{PropertyPath: "sku.size", Value: "X1"},
			},
			RequiredFields: []string{
				"properties.grafanaMajorVersion",
				"sku.name", // ResourceSku.Name is a non-pointer string required by the ARM API
			},
		},
	}
}

// Self-registers into the azwise registry.
func init() { azwise.Register(NewDashboardGrafana()) }
